mapper.insert:
insert into RECORD_ANALYSIS_GROUP(
  STUDENT_NO, STATUS
) VALUES(
  #{studentNo}
  ,#{status}
)

mapper.update:
update RECORD_ANALYSIS_GROUP
set
  COMPLETED_AT = SYSDATE
  ,status = #{status}
where GROUP_NO = #{groupNo}

mapper.select:
select count(*)
from RECORD_ANALYSIS_GROUP
where STUDENT_NO = #{studentNo}
and STATUS = #{status}

select STATUS
from RECORD_ANALYSIS_GROUP
where GROUP_NO = #{groupNo}
